pat = re.compile(r'\b(' + '|'.join(map(re.escape, sorted(INDO, key=len, reverse=True))) + r')\b', re.I)

# Exclude code identifiers/technical terms and fragments inside dense CSS/embedded assets.
hits = []
for line_no, line in enumerate(text.splitlines(), 1):
    if len(line) > 5000:
        continue
    # Look only at text-bearing parts of lines. Preserve whole source in output for manual review.
    if line.lstrip().startswith(('/*', '*', '}', '@media', 'html', ':root', '.modern-', '[data-theme')) and '<' not in line and '`' not in line:
        continue
    words = pat.findall(line)
    if words:
        hits.append((line_no, sorted(set(w.lower() for w in words)), line.strip()[:800]))

print('candidate lines with likely Indonesian terms:', len(hits))
for n, words, line in hits:
    print(f'{n}: {", ".join(words)}')
    print(' ', line)
